arguments.content:
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap');

:root {
  --primary: #0A1628; /* Deep Navy */
  --secondary: #012A2D; /* Dark Teal */
  --accent: #D2A74B; /* Gold */
  --accent-hover: #b8903c;
  --bg-light: #F8F9FA;
  --bg-gray: #E9ECEF;
  --text-dark: #212529;
  --text-body: #4A5568;
  --white: #FFFFFF;

  --font-main: 'Inter', sans-serif;

  --transition: all 0.3s ease;
  --shadow: 0 4px 6px rgba(0,0,0,0.05);
  --shadow-lg: 0 10px 25px rgba(0,0,0,0.1);
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: var(--font-main);
  color: var(--text-body);
  line-height: 1.6;
  background-color: var(--white);
  overflow-x: hidden;
}

h1, h2, h3, h4, h5, h6 {
  color: var(--primary);
  font-weight: 600;
  line-height: 1.2;
}

a {
  text-decoration: none;
  color: var(--primary);
  transition: var(--transition);
}

ul {
  list-style: none;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

.container {
  width: 100%;
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 2rem;
}

/* Header & Nav */
.site-header {
  background-color: var(--primary);
  color: var(--white);
  position: sticky;
  top: 0;
  z-index: 100;
  box-shadow: var(--shadow);
}

.header-inner {
  display: flex;
  justify-content: space-between;
  align-items: center;
  height: 80px;
}

.logo {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--white);
  letter-spacing: 1px;
}

.main-nav {
  display: flex;
  align-items: center;
}

.nav-list {
  display: flex;
  gap: 2rem;
}

.nav-item {
  position: relative;
}

.nav-link {
  color: var(--white);
  font-weight: 500;
  font-size: 0.95rem;
  padding: 1rem 0;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.nav-link:hover, .nav-item.active .nav-link {
  color: var(--accent);
}

/* Mega Menu */
.mega-menu {
  position: absolute;
  top: 100%;
  left: 50%;
  transform: translateX(-50%);
  width: 100vw;
  max-width: 1400px;
  background-color: var(--white);
  color: var(--text-dark);
  box-shadow: var(--shadow-lg);
  opacity: 0;
  visibility: hidden;
  transition: var(--transition);
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 3rem;
  padding: 3rem 2rem;
  border-top: 3px solid var(--accent);
}

.nav-item.has-dropdown:hover .mega-menu {
  opacity: 1;
  visibility: visible;
}

.mega-menu-section h4 {
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: var(--secondary);
  margin-bottom: 1.5rem;
  border-bottom: 1px solid var(--bg-gray);
  padding-bottom: 0.5rem;
}

.mega-menu-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1.5rem;
}

.mega-menu-link {
  display: block;
  font-size: 1rem;
  color: var(--text-dark);
  font-weight: 500;
  margin-bottom: 0.5rem;
}

.mega-menu-link:hover {
  color: var(--accent);
}

/* Mobile Nav Toggle */
.mobile-toggle {
  display: none;
  background: none;
  border: none;
  color: var(--white);
  font-size: 1.5rem;
  cursor: pointer;
}

/* Hero Section */
.hero {
  position: relative;
  min-height: 80vh;
  display: flex;
  align-items: center;
  background-color: var(--primary);
  color: var(--white);
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0.4;
  z-index: 1;
}

.hero-overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: linear-gradient(to right, rgba(10, 22, 40, 0.9) 0%, rgba(10, 22, 40, 0.4) 100%);
  z-index: 2;
}

.hero .container {
  position: relative;
  z-index: 3;
}

.hero-content {
  max-width: 800px;
}

.hero-title {
  font-size: 3.5rem;
  font-weight: 700;
  color: var(--white);
  margin-bottom: 1.5rem;
  line-height: 1.1;
}

.hero-subtitle {
  font-size: 1.25rem;
  font-weight: 300;
  margin-bottom: 2.5rem;
  opacity: 0.9;
}

.btn {
  display: inline-block;
  padding: 1rem 2rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1px;
  border-radius: 2px;
  cursor: pointer;
  border: none;
  transition: var(--transition);
}

.btn-primary {
  background-color: var(--accent);
  color: var(--white);
}

.btn-primary:hover {
  background-color: var(--accent-hover);
}

.btn-outline {
  background-color: transparent;
  color: var(--white);
  border: 2px solid var(--white);
}

.btn-outline:hover {
  background-color: var(--white);
  color: var(--primary);
}

.btn-dark {
  background-color: var(--primary);
  color: var(--white);
}
.btn-dark:hover {
  background-color: var(--secondary);
}

/* Sections */
.section {
  padding: 6rem 0;
}

.section-light {
  background-color: var(--bg-light);
}

.section-dark {
  background-color: var(--primary);
  color: var(--white);
}

.section-dark h2, .section-dark h3 {
  color: var(--white);
}

.section-header {
  margin-bottom: 4rem;
  max-width: 800px;
}

.section-title {
  font-size: 2.5rem;
  margin-bottom: 1rem;
}

/* Grids */
.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 2rem; }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 2rem; }
.grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: 2rem; }

/* Cards */
.card {
  background: var(--white);
  box-shadow: var(--shadow);
  border-radius: 4px;
  overflow: hidden;
  transition: var(--transition);
  display: flex;
  flex-direction: column;
  height: 100%;
}

.card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-5px);
}

.card-img {
  width: 100%;
  height: 240px;
  object-fit: cover;
}

.card-body {
  padding: 2rem;
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}

.card-tag {
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--accent);
  font-weight: 600;
  margin-bottom: 0.5rem;
  display: block;
}

.card-title {
  font-size: 1.25rem;
  margin-bottom: 1rem;
}

.card-text {
  margin-bottom: 1.5rem;
  flex-grow: 1;
}

.card-link {
  font-weight: 600;
  color: var(--secondary);
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-top: auto;
}

.card-link:hover {
  color: var(--accent);
}

/* Announcement Banner */
.announcement-banner {
  background-color: var(--secondary);
  color: var(--white);
  padding: 1rem 0;
  text-align: center;
}
.announcement-content {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 2rem;
  flex-wrap: wrap;
}
.announcement-text {
  font-weight: 500;
  font-size: 1rem;
}
.announcement-link {
  color: var(--accent);
  font-weight: 600;
  text-decoration: underline;
}

/* About Statement */
.about-statement {
  text-align: center;
  max-width: 900px;
  margin: 0 auto;
}
.about-statement h2 {
  font-size: 2rem;
  line-height: 1.4;
  font-weight: 300;
  margin-bottom: 2rem;
  color: var(--text-dark);
}

/* Tabs: What We Do */
.tabs-container {
  display: grid;
  grid-template-columns: 300px 1fr;
  gap: 4rem;
  background: var(--white);
  box-shadow: var(--shadow-lg);
  border-radius: 8px;
  overflow: hidden;
}

.tabs-nav {
  background-color: var(--bg-light);
  display: flex;
  flex-direction: column;
}

.tab-btn {
  padding: 2rem;
  text-align: left;
  background: none;
  border: none;
  border-left: 4px solid transparent;
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--text-body);
  cursor: pointer;
  transition: var(--transition);
  font-family: var(--font-main);
}

.tab-btn:hover {
  background-color: rgba(0,0,0,0.02);
}

.tab-btn.active {
  background-color: var(--white);
  color: var(--primary);
  border-left-color: var(--accent);
}

.tab-content {
  padding: 4rem 4rem 4rem 0;
}

.tab-pane {
  display: none;
  animation: fadeIn 0.5s ease;
}

.tab-pane.active {
  display: block;
}

.tab-pane h3 {
  font-size: 2rem;
  margin-bottom: 1.5rem;
}

.tab-pane p {
  font-size: 1.1rem;
  margin-bottom: 2rem;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

/* Newsletter */
.newsletter-section {
  background-color: var(--primary);
  color: var(--white);
  padding: 5rem 0;
}
.newsletter-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}
.newsletter-form {
  display: flex;
  gap: 1rem;
}
.newsletter-input {
  flex-grow: 1;
  padding: 1rem 1.5rem;
  border: none;
  border-radius: 2px;
  font-family: var(--font-main);
  font-size: 1rem;
}

/* Footer */
.site-footer {
  background-color: var(--primary);
  color: var(--white);
  padding: 5rem 0 2rem;
  border-top: 1px solid rgba(255,255,255,0.1);
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 3rem;
  margin-bottom: 4rem;
}
.footer-logo {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--white);
  margin-bottom: 1.5rem;
  display: block;
}
.footer-col h4 {
  color: var(--accent);
  margin-bottom: 1.5rem;
  font-size: 1rem;
  text-transform: uppercase;
  letter-spacing: 1px;
}
.footer-links li {
  margin-bottom: 0.75rem;
}
.footer-links a {
  color: rgba(255,255,255,0.7);
}
.footer-links a:hover {
  color: var(--white);
}
.footer-bottom {
  padding-top: 2rem;
  border-top: 1px solid rgba(255,255,255,0.1);
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.85rem;
  color: rgba(255,255,255,0.5);
}
.footer-legal {
  display: flex;
  gap: 1.5rem;
}
.footer-legal a {
  color: rgba(255,255,255,0.5);
}
.footer-legal a:hover {
  color: var(--white);
}

/* Page Headers */
.page-header {
  background-color: var(--primary);
  color: var(--white);
  padding: 6rem 0;
  text-align: center;
  position: relative;
}

.page-header h1 {
  font-size: 3rem;
  color: var(--white);
  margin-bottom: 1rem;
}

.page-header p {
  font-size: 1.25rem;
  opacity: 0.9;
  max-width: 700px;
  margin: 0 auto;
}

/* Service Detail Layout */
.service-intro {
  font-size: 1.25rem;
  max-width: 900px;
  margin: 0 auto;
  text-align: center;
}

.capabilities-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(350px, 1fr));
  gap: 2rem;
}

.capability-card {
  padding: 2.5rem;
  background: var(--white);
  border: 1px solid var(--bg-gray);
  border-radius: 4px;
  transition: var(--transition);
}

.capability-card:hover {
  border-color: var(--accent);
  box-shadow: var(--shadow);
}

.capability-card h4 {
  font-size: 1.25rem;
  margin-bottom: 1rem;
  color: var(--primary);
}

/* Utilities */
.text-center { text-align: center; }
.mt-2 { margin-top: 2rem; }
.mb-2 { margin-bottom: 2rem; }
.mb-4 { margin-bottom: 4rem; }

/* Responsive */
@media (max-width: 1024px) {
  .hero-title { font-size: 2.5rem; }
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }

  .tabs-container {
    grid-template-columns: 1fr;
    gap: 0;
  }
  .tabs-nav {
    flex-direction: row;
    overflow-x: auto;
  }
  .tab-btn {
    border-left: none;
    border-bottom: 4px solid transparent;
    padding: 1rem 2rem;
    white-space: nowrap;
  }
  .tab-btn.active {
    border-left-color: transparent;
    border-bottom-color: var(--accent);
  }
  .tab-content {
    padding: 2rem;
  }
}

@media (max-width: 768px) {
  .nav-list {
    position: fixed;
    top: 80px;
    left: -100%;
    width: 100%;
    height: calc(100vh - 80px);
    background-color: var(--primary);
    flex-direction: column;
    padding: 2rem;
    transition: var(--transition);
    overflow-y: auto;
    z-index: 99;
  }
  .nav-list.active {
    left: 0;
  }
  .mobile-toggle {
    display: block;
  }

  .mega-menu {
    position: static;
    transform: none;
    width: 100%;
    opacity: 1;
    visibility: visible;
    box-shadow: none;
    padding: 1rem 0 1rem 1rem;
    display: none; /* Hide by default in mobile, toggle via JS */
    grid-template-columns: 1fr;
    gap: 1.5rem;
    background-color: rgba(255,255,255,0.05);
    border-top: none;
  }

  .mega-menu.active {
    display: grid;
  }

  .mega-menu-link {
    color: var(--white);
  }
  .mega-menu-section h4 {
    color: var(--accent);
    border-bottom-color: rgba(255,255,255,0.1);
  }

  .grid-2, .grid-3 { grid-template-columns: 1fr; }
  .newsletter-grid { grid-template-columns: 1fr; gap: 2rem; }
  .newsletter-form { flex-direction: column; }

  .hero-title { font-size: 2rem; }
  .section { padding: 4rem 0; }

  .footer-bottom {
    flex-direction: column;
    gap: 1rem;
    text-align: center;
  }
  .footer-legal {
    flex-wrap: wrap;
    justify-content: center;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  // Mobile Menu Toggle
  const mobileToggle = document.querySelector('.mobile-toggle');
  const navList = document.querySelector('.nav-list');

  if (mobileToggle && navList) {
    mobileToggle.addEventListener('click', () => {
      navList.classList.toggle('active');
      const isExpanded = mobileToggle.getAttribute('aria-expanded') === 'true';
      mobileToggle.setAttribute('aria-expanded', !isExpanded);
    });
  }

  // Mobile Accordion for Mega Menu
  const hasDropdownLinks = document.querySelectorAll('.nav-item.has-dropdown > .nav-link');

  hasDropdownLinks.forEach(link => {
    link.addEventListener('click', (e) => {
      if (window.innerWidth <= 768) {
        e.preventDefault();
        const megaMenu = link.nextElementSibling;
        if (megaMenu && megaMenu.classList.contains('mega-menu')) {
          megaMenu.classList.toggle('active');
        }
      }
    });
  });

  // What We Do Tabs
  const tabBtns = document.querySelectorAll('.tab-btn');
  const tabPanes = document.querySelectorAll('.tab-pane');

  if (tabBtns.length > 0) {
    tabBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        // Remove active class from all
        tabBtns.forEach(b => b.classList.remove('active'));
        tabPanes.forEach(p => p.classList.remove('active'));

        // Add active to clicked
        btn.classList.add('active');
        const targetId = btn.getAttribute('data-target');
        document.getElementById(targetId).classList.add('active');
      });
    });
  }
});
